"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[83768],{98974:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"AutoCannonController","desc":"Renders every placed AutoCannon for all players. Keeps one `TurretRig`\\n(`TrainTurret`) per turret in `workspace.PlacedObjects` (`Discovery` follows the\\nPlaceableName attribute and drops the rig when the turret is removed or\\nstashed), eases it toward the replicated `AimYaw` / `AimPitch`, and draws\\n`AutoCannonFired` shots: barrel fold (a per-turret `Recoil` written after the\\nrig updates), muzzle flash, a pooled neon tracer and the fire sound. Impact\\nsound comes from `ExplosionAt` (\\"AutoCannon\\"); the reload sound plays once\\nwhen `Reloading` turns true. Shots whose shooter is the local player while the\\nlocal player mans that turret are skipped: the `Gunner` hooks below predict\\nthem. The tracers are client-only Parts. `Gunner` also gets each turret\'s\\nmount prompt and its step runs first in the per-frame order.","realm":["Client"],"source":{"line":18,"path":"src/StarterPlayer/StarterPlayerScripts/AutoCannonController/init.client.luau"}}')}}]);